class Solution {

    /**
     * @param Integer[] $salary
     * @return Float
     */
    function average($salary) {
        $sum = 0;
        $minSalary = PHP_INT_MAX;
        $maxSalary = PHP_INT_MIN;

        foreach ($salary as $s) {
            $sum += $s;
            if ($s < $minSalary) {
                $minSalary = $s;
            }
            if ($s > $maxSalary) {
                $maxSalary = $s;
            }
        }

        return ($sum - $minSalary - $maxSalary) / (count($salary) - 2);
    }
}
