<?php
class Solution {
    private $parent = [];
    private $sz = [];

    private function find($x) {
        while ($this->parent[$x] !== $x) {
            $this->parent[$x] = $this->parent[$this->parent[$x]];
            $x = $this->parent[$x];
        }
        return $x;
    }

    private function union($a, $b) {
        $ra = $this->find($a);
        $rb = $this->find($b);

        if ($ra === $rb) {
            return;
        }

        if ($this->sz[$ra] < $this->sz[$rb]) {
            $tmp = $ra;
            $ra = $rb;
            $rb = $tmp;
        }

        $this->parent[$rb] = $ra;
        $this->sz[$ra] += $this->sz[$rb];
    }

    /**
     * @param Integer[][] $grid
     * @param Integer[][] $hits
     * @return Integer[]
     */
    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $roof = $m * $n;
        $total = $roof + 1;

        $this->parent = range(0, $roof);
        $this->sz = array_fill(0, $total, 1);

        $work = $grid;
        $hitCount = count($hits);
        $result = array_fill(0, $hitCount, 0);

        for ($i = 0; $i < $hitCount; $i++) {
            $r = $hits[$i][0];
            $c = $hits[$i][1];

            if ($work[$r][$c] === 1) {
                $work[$r][$c] = 0;
            }
        }

        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                if ($work[$r][$c] !== 1) {
                    continue;
                }

                $id = $r * $n + $c;

                if ($r === 0) {
                    $this->union($id, $roof);
                }

                if ($r > 0 && $work[$r - 1][$c] === 1) {
                    $this->union($id, ($r - 1) * $n + $c);
                }

                if ($c > 0 && $work[$r][$c - 1] === 1) {
                    $this->union($id, $r * $n + $c - 1);
                }
            }
        }

        for ($i = $hitCount - 1; $i >= 0; $i--) {
            $r = $hits[$i][0];
            $c = $hits[$i][1];

            if ($grid[$r][$c] !== 1) {
                continue;
            }

            $before = $this->sz[$this->find($roof)];

            $work[$r][$c] = 1;
            $id = $r * $n + $c;

            if ($r === 0) {
                $this->union($id, $roof);
            }

            if ($r > 0 && $work[$r - 1][$c] === 1) {
                $this->union($id, ($r - 1) * $n + $c);
            }

            if ($r + 1 < $m && $work[$r + 1][$c] === 1) {
                $this->union($id, ($r + 1) * $n + $c);
            }

            if ($c > 0 && $work[$r][$c - 1] === 1) {
                $this->union($id, $r * $n + $c - 1);
            }

            if ($c + 1 < $n && $work[$r][$c + 1] === 1) {
                $this->union($id, $r * $n + $c + 1);
            }

            $after = $this->sz[$this->find($roof)];
            $fallen = $after - $before - 1;

            $result[$i] = $fallen > 0 ? $fallen : 0;
        }

        return $result;
    }
}
