<?php
class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $mod = 1000000007;
        sort($arr, SORT_NUMERIC);

        $n = count($arr);
        $index = [];
        for ($i = 0; $i < $n; $i++) {
            $index[$arr[$i]] = $i;
        }

        $dp = array_fill(0, $n, 1);
        $ans = 0;

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $i; $j++) {
                if ($arr[$i] % $arr[$j] == 0) {
                    $right = intdiv($arr[$i], $arr[$j]);
                    if (isset($index[$right])) {
                        $k = $index[$right];
                        $dp[$i] = ($dp[$i] + ($dp[$j] * $dp[$k]) % $mod) % $mod;
                    }
                }
            }
            $ans = ($ans + $dp[$i]) % $mod;
        }

        return $ans;
    }
}
