class Solution {

    /**
     * @param Integer $n
     * @return Integer
     */
    function countVowelPermutation($n) {
        $mod = 1000000007;

        $a = 1;
        $e = 1;
        $i = 1;
        $o = 1;
        $u = 1;

        for ($len = 2; $len <= $n; $len++) {
            $newA = ($e + $i + $u) % $mod;
            $newE = ($a + $i) % $mod;
            $newI = ($e + $o) % $mod;
            $newO = $i % $mod;
            $newU = ($i + $o) % $mod;

            $a = $newA;
            $e = $newE;
            $i = $newI;
            $o = $newO;
            $u = $newU;
        }

        return ($a + $e + $i + $o + $u) % $mod;
    }
}
