    /**
     * @param Integer $n
     * @return Integer
     */
    function clumsy($n) {
        $stack = [$n];
        $op = 0;

        for ($i = $n - 1; $i >= 1; $i--) {
            if ($op == 0) {
                $last = array_pop($stack);
                $stack[] = $last * $i;
            } elseif ($op == 1) {
                $last = array_pop($stack);
                $stack[] = intdiv($last, $i);
            } elseif ($op == 2) {
                $stack[] = $i;
            } else {
                $stack[] = -$i;
            }

            $op = ($op + 1) % 4;
        }

        return array_sum($stack);
    }
}
