     * @param Integer $m
     * @param Integer $k
     */
    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;
        $this->countTree = array_fill(0, $this->maxVal + 2, 0);
        $this->sumTree = array_fill(0, $this->maxVal + 2, 0);

        $this->bitMask = 1;
        while (($this->bitMask << 1) <= $this->maxVal) {
            $this->bitMask <<= 1;
        }
    }

