<?php
class Solution {

    /**
     * @param String[] $queries
     * @param String[] $words
     * @return Integer[]
     */
    function numSmallerByFrequency($queries, $words) {
        $frequency = function($s) {
            $minChar = '{';
            $count = 0;
            $len = strlen($s);

            for ($i = 0; $i < $len; $i++) {
                if ($s[$i] < $minChar) {
                    $minChar = $s[$i];
                    $count = 1;
                } elseif ($s[$i] === $minChar) {
                    $count++;
                }
            }

            return $count;
        };

        $wordFreqs = [];
        foreach ($words as $word) {
            $wordFreqs[] = $frequency($word);
        }

        sort($wordFreqs, SORT_NUMERIC);
        $n = count($wordFreqs);
        $answer = [];

        foreach ($queries as $query) {
            $qFreq = $frequency($query);

            $left = 0;
            $right = $n;

            while ($left < $right) {
                $mid = intdiv($left + $right, 2);

                if ($wordFreqs[$mid] <= $qFreq) {
                    $left = $mid + 1;
                } else {
                    $right = $mid;
                }
            }

            $answer[] = $n - $left;
        }

        return $answer;
    }
}
