        $bits = array_fill(0, $size, 0);
        for ($mask = 1; $mask < $size; $mask++) {
            $bits[$mask] = $bits[$mask >> 1] + ($mask & 1);
        }

        $dp = array_fill(0, $size, 0);

        for ($mask = 0; $mask < $size; $mask++) {
            $count = $bits[$mask];
            if (($count & 1) != 0) {
