    private function countIslands(&$grid) {
        $m = count($grid);
        $n = count($grid[0]);
        $visited = array_fill(0, $m, array_fill(0, $n, false));
        $count = 0;

        $dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
                if ($grid[$i][$j] == 1 && !$visited[$i][$j]) {
                    $count++;

                    if ($count > 1) {
                        return $count;
                    }

                    $stack = [[$i, $j]];
                    $visited[$i][$j] = true;

                    while (!empty($stack)) {
                        [$r, $c] = array_pop($stack);

                        foreach ($dirs as $dir) {
                            $nr = $r + $dir[0];
                            $nc = $c + $dir[1];

