 */
class Solution {

    /**
     * @param TreeNode $root
     * @return Integer
     */
    function minDepth($root) {
        if ($root === null) {
            return 0;
        }

        $queue = new SplQueue();
        $queue->enqueue([$root, 1]);

        while (!$queue->isEmpty()) {
            list($node, $depth) = $queue->dequeue();

            if ($node->left === null && $node->right === null) {
                return $depth;
            }

            if ($node->left !== null) {
                $queue->enqueue([$node->left, $depth + 1]);
            }

            if ($node->right !== null) {
                $queue->enqueue([$node->right, $depth + 1]);
            }
        }

        return 0;
    }
}
