class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function numOfWays($nums) {
        $MOD = 1000000007;
        $n = count($nums);

        $modPow = function($base, $exp) use ($MOD) {
            $result = 1;
            $base %= $MOD;

            while ($exp > 0) {
                if (($exp & 1) == 1) {
                    $result = ($result * $base) % $MOD;
                }
                $base = ($base * $base) % $MOD;
                $exp = intdiv($exp, 2);
            }

            return $result;
        };

        $fact = array_fill(0, $n + 1, 1);
        for ($i = 1; $i <= $n; $i++) {
            $fact[$i] = ($fact[$i - 1] * $i) % $MOD;
        }

        $invFact = array_fill(0, $n + 1, 1);
        $invFact[$n] = $modPow($fact[$n], $MOD - 2);
        for ($i = $n; $i >= 1; $i--) {
            $invFact[$i - 1] = ($invFact[$i] * $i) % $MOD;
        }

        $dfs = function($arr) use (&$dfs, &$fact, &$invFact, $MOD) {
            $len = count($arr);

            if ($len <= 2) {
                return 1;
            }

            $root = $arr[0];
            $left = [];
            $right = [];

            for ($i = 1; $i < $len; $i++) {
                if ($arr[$i] < $root) {
                    $left[] = $arr[$i];
                } else {
                    $right[] = $arr[$i];
                }
            }

            $leftCount = count($left);
            $rightCount = count($right);

            $comb = $fact[$leftCount + $rightCount];
            $comb = ($comb * $invFact[$leftCount]) % $MOD;
            $comb = ($comb * $invFact[$rightCount]) % $MOD;

            $leftWays = $dfs($left);
            $rightWays = $dfs($right);

            return ((($comb * $leftWays) % $MOD) * $rightWays) % $MOD;
        };

        return ($dfs($nums) - 1 + $MOD) % $MOD;
    }
}
