    /**
     * @param Integer[] $bloomDay
     * @param Integer $m
     * @param Integer $k
     * @return Integer
     */
    function minDays($bloomDay, $m, $k) {
        $n = count($bloomDay);

        if ($m * $k > $n) {
            return -1;
        }

        $low = PHP_INT_MAX;
        $high = 0;

        foreach ($bloomDay as $day) {
            if ($day < $low) {
                $low = $day;
            }
            if ($day > $high) {
                $high = $day;
            }
        }

        while ($low < $high) {
            $mid = intdiv($low + $high, 2);

            $bouquets = 0;
            $flowers = 0;

            foreach ($bloomDay as $day) {
                if ($day <= $mid) {
                    $flowers++;

                    if ($flowers == $k) {
                        $bouquets++;
                        $flowers = 0;

                        if ($bouquets >= $m) {
                            break;
                        }
                    }
                } else {
                    $flowers = 0;
                }
            }

            if ($bouquets >= $m) {
                $high = $mid;
            } else {
                $low = $mid + 1;
            }
        }

        return $low;
    }
