class Solution {

    /**
     * @param Integer[] $tasks
     * @param Integer $sessionTime
     * @return Integer
     */
    function minSessions($tasks, $sessionTime) {
        $n = count($tasks);
        rsort($tasks);

        $totalMasks = 1 << $n;
        $inf = 1 << 30;

        $sessions = array_fill(0, $totalMasks, $inf);
        $used = array_fill(0, $totalMasks, $inf);

        $sessions[0] = 1;
        $used[0] = 0;

        for ($mask = 0; $mask < $totalMasks; $mask++) {
            if ($sessions[$mask] == $inf) {
                continue;
            }

            $curSessions = $sessions[$mask];
            $curUsed = $used[$mask];

            for ($i = 0; $i < $n; $i++) {
                if ((($mask >> $i) & 1) == 1) {
                    continue;
                }

                $newMask = $mask | (1 << $i);
                $taskTime = $tasks[$i];

                if ($curUsed + $taskTime <= $sessionTime) {
                    $newSessions = $curSessions;
                    $newUsed = $curUsed + $taskTime;
                } else {
                    $newSessions = $curSessions + 1;
                    $newUsed = $taskTime;
                }

                if (
                    $newSessions < $sessions[$newMask] ||
                    ($newSessions == $sessions[$newMask] && $newUsed < $used[$newMask])
                ) {
                    $sessions[$newMask] = $newSessions;
                    $used[$newMask] = $newUsed;
                }
            }
        }

        return $sessions[$totalMasks - 1];
    }
}
