     */
    function nextGreaterElements($nums) {
        $n = count($nums);
        $result = array_fill(0, $n, -1);
        $stack = [];
        $top = -1;

        for ($i = 0; $i < 2 * $n; $i++) {
            $idx = $i % $n;

            while ($top >= 0 && $nums[$stack[$top]] < $nums[$idx]) {
                $result[$stack[$top]] = $nums[$idx];
                $top--;
