class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function removeInvalidParentheses($s) {
        $n = strlen($s);
        $leftRemove = 0;
        $rightRemove = 0;

        for ($i = 0; $i < $n; $i++) {
            $ch = $s[$i];
            if ($ch === '(') {
                $leftRemove++;
            } elseif ($ch === ')') {
                if ($leftRemove > 0) {
                    $leftRemove--;
                } else {
                    $rightRemove++;
                }
            }
        }

        $result = [];

        $dfs = function($index, $balance, $leftRemove, $rightRemove, $path) use (&$dfs, &$result, $s, $n) {
            if ($n - $index < $leftRemove + $rightRemove) {
                return;
            }

            if ($index === $n) {
                if ($balance === 0 && $leftRemove === 0 && $rightRemove === 0) {
                    $result[$path] = true;
                }
                return;
            }

            $ch = $s[$index];

            if ($ch === '(') {
                if ($leftRemove > 0) {
                    $dfs($index + 1, $balance, $leftRemove - 1, $rightRemove, $path);
                }
                $dfs($index + 1, $balance + 1, $leftRemove, $rightRemove, $path . $ch);
            } elseif ($ch === ')') {
                if ($rightRemove > 0) {
                    $dfs($index + 1, $balance, $leftRemove, $rightRemove - 1, $path);
                }
                if ($balance > 0) {
                    $dfs($index + 1, $balance - 1, $leftRemove, $rightRemove, $path . $ch);
                }
            } else {
                $dfs($index + 1, $balance, $leftRemove, $rightRemove, $path . $ch);
            }
        };

        $dfs(0, 0, $leftRemove, $rightRemove, "");

        return array_keys($result);
    }
}
