class Solution {

    /**
     * @param String $s1
     * @param String $s2
     * @return Boolean
     */
    function isScramble($s1, $s2) {
        $n = strlen($s1);

        if ($s1 === $s2) {
            return true;
        }

        if (count_chars($s1, 1) != count_chars($s2, 1)) {
            return false;
        }

        $memo = [];

        $dfs = function($a, $b) use (&$dfs, &$memo) {
            if ($a === $b) {
                return true;
            }

            $key = $a . "#" . $b;
            if (isset($memo[$key])) {
                return $memo[$key];
            }

            if (count_chars($a, 1) != count_chars($b, 1)) {
                $memo[$key] = false;
                return false;
            }

            $len = strlen($a);

            for ($i = 1; $i < $len; $i++) {
                if (
                    $dfs(substr($a, 0, $i), substr($b, 0, $i)) &&
                    $dfs(substr($a, $i), substr($b, $i))
                ) {
                    $memo[$key] = true;
                    return true;
                }

                if (
                    $dfs(substr($a, 0, $i), substr($b, $len - $i)) &&
                    $dfs(substr($a, $i), substr($b, 0, $len - $i))
                ) {
                    $memo[$key] = true;
                    return true;
                }
            }

            $memo[$key] = false;
            return false;
        };

        return $dfs($s1, $s2);
    }
}
