<?php
class Solution {
    private $small;
    private $large;
    private $delayed;
    private $smallSize;
    private $largeSize;

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Float[]
     */
    function medianSlidingWindow($nums, $k) {
        $this->small = new SplPriorityQueue();
        $this->large = new SplPriorityQueue();
        $this->small->setExtractFlags(SplPriorityQueue::EXTR_DATA);
        $this->large->setExtractFlags(SplPriorityQueue::EXTR_DATA);

        $this->delayed = [];
        $this->smallSize = 0;
        $this->largeSize = 0;

        $n = count($nums);
        $ans = [];

        for ($i = 0; $i < $k; $i++) {
            $this->addNum($nums[$i]);
        }

        $ans[] = $this->getMedian($k);

        for ($i = $k; $i < $n; $i++) {
            $this->addNum($nums[$i]);
            $this->removeNum($nums[$i - $k]);
            $ans[] = $this->getMedian($k);
        }

        return $ans;
    }

    private function addNum($num) {
        $this->prune($this->small);

        if ($this->small->isEmpty() || $num <= $this->small->top()) {
            $this->small->insert($num, $num);
            $this->smallSize++;
        } else {
            $this->large->insert($num, -$num);
            $this->largeSize++;
        }

        $this->rebalance();
    }

    private function removeNum($num) {
        $this->prune($this->small);
        $this->prune($this->large);

        if (!$this->small->isEmpty() && $num <= $this->small->top()) {
            $this->smallSize--;
            if (!isset($this->delayed[$num])) {
                $this->delayed[$num] = 0;
            }
            $this->delayed[$num]++;

            if (!$this->small->isEmpty() && $num == $this->small->top()) {
                $this->prune($this->small);
            }
        } else {
            $this->largeSize--;
            if (!isset($this->delayed[$num])) {
                $this->delayed[$num] = 0;
            }
            $this->delayed[$num]++;

            if (!$this->large->isEmpty() && $num == $this->large->top()) {
                $this->prune($this->large);
            }
        }

        $this->rebalance();
    }

    private function rebalance() {
        if ($this->smallSize > $this->largeSize + 1) {
            $this->prune($this->small);
            $num = $this->small->extract();
            $this->large->insert($num, -$num);
            $this->smallSize--;
            $this->largeSize++;
            $this->prune($this->small);
        } elseif ($this->smallSize < $this->largeSize) {
            $this->prune($this->large);
            $num = $this->large->extract();
            $this->small->insert($num, $num);
            $this->largeSize--;
            $this->smallSize++;
            $this->prune($this->large);
        }
    }

    private function prune($heap) {
        while (!$heap->isEmpty()) {
            $num = $heap->top();

            if (isset($this->delayed[$num]) && $this->delayed[$num] > 0) {
                $heap->extract();
                $this->delayed[$num]--;

                if ($this->delayed[$num] == 0) {
                    unset($this->delayed[$num]);
                }
            } else {
                break;
            }
        }
    }

    private function getMedian($k) {
        $this->prune($this->small);
        $this->prune($this->large);

        if ($k % 2 == 1) {
            return (float)$this->small->top();
        }

        return ($this->small->top() + $this->large->top()) / 2.0;
    }
}
