    private $children = [];
    private $isEnd = [];
    private $stream = '';
    private $maxLen = 0;
    private $nodeCount = 1;

    /**
     * @param String[] $words
     */
    function __construct($words) {
        foreach ($words as $word) {
            $len = strlen($word);
            if ($len > $this->maxLen) {
                $this->maxLen = $len;
            }

            $node = 0;
            for ($i = $len - 1; $i >= 0; $i--) {
                $code = ord($word[$i]) - 97;
                $key = $node * 26 + $code;

                if (!isset($this->children[$key])) {
                    $this->children[$key] = $this->nodeCount++;
                }

                $node = $this->children[$key];
            }

            $this->isEnd[$node] = true;
        }
    }

    /**
     * @param String $letter
     * @return Boolean
     */
    function query($letter) {
        $this->stream .= $letter;

        $len = strlen($this->stream);
        if ($len > $this->maxLen) {
            $this->stream = substr($this->stream, -$this->maxLen);
            $len = $this->maxLen;
        }

        $node = 0;
        for ($i = $len - 1; $i >= 0; $i--) {
            $code = ord($this->stream[$i]) - 97;
            $key = $node * 26 + $code;

            if (!isset($this->children[$key])) {
                return false;
            }

            $node = $this->children[$key];

            if (isset($this->isEnd[$node])) {
                return true;
            }
        }

        return false;
    }
