class Solution {

    /**
     * @param String $beginWord
     * @param String $endWord
     * @param String[] $wordList
     * @return Integer
     */
    function ladderLength($beginWord, $endWord, $wordList) {
        $wordSet = [];
        foreach ($wordList as $word) {
            $wordSet[$word] = true;
        }

        if (!isset($wordSet[$endWord])) {
            return 0;
        }

        unset($wordSet[$beginWord]);
        unset($wordSet[$endWord]);

        $front = [$beginWord => true];
        $back = [$endWord => true];
        $length = strlen($beginWord);
        $steps = 1;
        $letters = range('a', 'z');

        while (!empty($front) && !empty($back)) {
            if (count($front) > count($back)) {
                $temp = $front;
                $front = $back;
                $back = $temp;
            }

            $next = [];

            foreach ($front as $word => $_) {
                for ($i = 0; $i < $length; $i++) {
                    $originalChar = $word[$i];

                    foreach ($letters as $ch) {
                        if ($ch === $originalChar) {
                            continue;
                        }

                        $candidate = $word;
                        $candidate[$i] = $ch;

                        if (isset($back[$candidate])) {
                            return $steps + 1;
                        }

                        if (isset($wordSet[$candidate])) {
                            $next[$candidate] = true;
                            unset($wordSet[$candidate]);
                        }
                    }
                }
            }

            $front = $next;
            $steps++;
        }

        return 0;
    }
}
